const body = $input.first().json.body ?? $input.first().json;
const a = body.analysis ?? {};
const v = a.verification ?? {};
const issues = (a.issues ?? []).slice(0, 5).map(x => `• ${String(x.severity ?? 'INFO').toUpperCase()}: ${x.issue}`).join('\n') || 'None identified';
const steps = (a.steps ?? []).slice(0, 5).map((x, i) => `${i + 1}. ${x.title}: ${x.explanation}`).join('\n') || 'Not provided';
const tests = (a.test_cases ?? []).slice(0, 3).map(x => `• ${x.name}: ${x.expected_behavior}`).join('\n') || 'Not provided';
const lines = [
  '*CodeWise AI — Code Intelligence Report*',
  `*Language:* ${a.language ?? 'Unknown'}`,
  `*Summary:* ${a.summary ?? 'No summary'}`,
  `*Explanation:* ${a.explanation ?? 'Not provided'}`,
  `*Walkthrough:*\n${steps}`,
  `*Improvement:* ${a.improvement ?? 'Not provided'}`,
  `*Issues:*\n${issues}`,
  `*Suggested tests:*\n${tests}`,
  `*Agent verification:* ${v.status ?? 'Not available'}`,
  `*Verification note:* ${v.note ?? 'Not provided'}`
];
return [{ json: { text: lines.join('\n') } }];
